def r(x):
    x = float(x)
    t = 4.0 * x - 2.0
    t_perturbed = t + (2.0 - t) * 0.1  # Move t toward upper asymptote (2.0), hence x toward 1.0
    x_perturbed = (t_perturbed + 2.0) / 4.0
    return max(min(x_perturbed, 1.0), 0.0)

def R(y_orig, y_new):
